css:
.itaudit-sim-container {
    padding: 28px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: 'Courier New', 'SF Mono', 'Fira Code', monospace;
    color: #c9d1d9;
}
.itaudit-sim-header {
    border-left: 4px solid #00ff88;
    padding: 24px 28px;
    margin-bottom: 24px;
    background: linear-gradient(135deg, rgba(0,255,136,0.06) 0%, rgba(0,191,255,0.04) 100%);
    border-radius: 0 8px 8px 0;
    position: relative;
}
.itaudit-sim-header-badge {
    display: inline-block;
    background: rgba(0,255,136,0.12);
    border: 1px solid rgba(0,255,136,0.3);
    color: #00ff88;
    font-size: 0.65rem;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    padding: 4px 12px;
    border-radius: 4px;
    margin-bottom: 12px;
}
.itaudit-sim-header h1 {
    color: #00ff88;
    font-size: 1.5rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin: 0 0 6px 0;
    text-shadow: 0 0 20px rgba(0,255,136,0.3);
}
.itaudit-sim-subtitle {
    color: #6b7280;
    font-size: 0.85rem;
    margin: 0;
    letter-spacing: 0.05em;
}
.itaudit-sim-period-counter {
    text-align: center;
    color: #8b949e;
    font-size: 0.9rem;
    margin-bottom: 24px;
    padding: 10px;
    background: #111827;
    border-radius: 6px;
    border: 1px solid #1f2d3d;
    letter-spacing: 0.1em;
}
.itaudit-sim-period-counter span {
    margin: 0 4px;
}
.itaudit-sim-period-counter #currentDay {
    color: #00ff88;
    font-weight: 700;
    font-size: 1.1rem;
}
.itaudit-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 28px;
}
.itaudit-sim-kpi-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px 16px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.itaudit-sim-kpi-card:hover {
    border-color: #2d4a5d;
    box-shadow: 0 0 16px rgba(0,191,255,0.08);
}
.itaudit-sim-kpi-accent {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    border-radius: 8px 8px 0 0;
}
.itaudit-sim-kpi-label {
    color: #6b7280;
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 10px;
}
.itaudit-sim-kpi-value {
    font-size: 1.9rem;
    font-weight: 700;
    color: #e0e6f0;
    line-height: 1;
}
.itaudit-risk-value {
    color: #ff4757;
}
.itaudit-sim-briefing {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
}
.itaudit-sim-briefing-bar {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, #ffa502, #ff6348);
}
.itaudit-sim-briefing h3 {
    color: #ffa502;
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin: 0 0 14px 0;
}
.itaudit-sim-briefing-body {
    color: #8b949e;
    font-size: 0.85rem;
    line-height: 1.7;
}
.itaudit-sim-controls {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 28px;
}
.itaudit-sim-controls h3 {
    color: #00bfff;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 0 0 20px 0;
}
.itaudit-sim-control-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 20px;
}
.itaudit-sim-control-group label {
    display: block;
    color: #8b949e;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
}
.itaudit-sim-control-group select,
.itaudit-sim-control-group input[type="number"] {
    width: 100%;
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 6px;
    padding: 10px 14px;
    font-family: inherit;
    font-size: 0.9rem;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.itaudit-sim-control-group select:focus,
.itaudit-sim-control-group input[type="number"]:focus {
    outline: none;
    border-color: #00bfff;
    box-shadow: 0 0 0 3px rgba(0,191,255,0.15);
}
.itaudit-sim-control-group select option {
    background: #111827;
    color: #e0e6f0;
}
.itaudit-sim-input-hint {
    display: block;
    color: #4b5563;
    font-size: 0.7rem;
    margin-top: 6px;
    letter-spacing: 0.05em;
}
.itaudit-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
}
.itaudit-sim-submit {
    background: linear-gradient(135deg, #00cc6a, #00a854) !important;
    border: none !important;
    color: #0a0f1e !important;
    font-family: inherit;
    font-weight: 700;
    font-size: 0.85rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 12px 32px;
    border-radius: 6px;
    transition: box-shadow 0.2s ease, transform 0.15s ease;
    cursor: pointer;
}
.itaudit-sim-submit:hover {
    box-shadow: 0 0 20px rgba(0,255,136,0.3);
    transform: translateY(-1px);
}
.itaudit-sim-undo {
    background: transparent !important;
    border: 1px solid #2d3f55 !important;
    color: #6b7280 !important;
    font-family: inherit;
    font-size: 0.75rem;
    letter-spacing: 0.06em;
    padding: 8px 16px;
    border-radius: 6px;
    cursor: pointer;
    transition: border-color 0.2s ease;
}
.itaudit-sim-undo:hover {
    border-color: #4b5563 !important;
    color: #8b949e !important;
}
.itaudit-sim-history {
    margin-bottom: 28px;
}
.itaudit-sim-history table {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    overflow: hidden;
    color: #c9d1d9;
    width: 100%;
    font-size: 0.8rem;
}
.itaudit-sim-history table th {
    background: #0d1422;
    color: #6b7280;
    text-transform: uppercase;
    font-size: 0.68rem;
    letter-spacing: 0.1em;
    padding: 12px 14px;
    border-bottom: 1px solid #1f2d3d;
}
.itaudit-sim-history table td {
    padding: 10px 14px;
    border-bottom: 1px solid #161f2e;
}
.itaudit-sim-history table tr:last-child td {
    border-bottom: none;
}
.itaudit-sim-chart {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px;
    height: 320px;
}
@media (max-width: 768px) {
    .itaudit-sim-container {
        padding: 16px;
    }
    .itaudit-sim-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .itaudit-sim-kpi-value {
        font-size: 1.4rem;
    }
    .itaudit-sim-control-row {
        grid-template-columns: 1fr;
        gap: 14px;
    }
    .itaudit-sim-header h1 {
        font-size: 1.1rem;
    }
    .itaudit-sim-btn-row {
        flex-direction: column;
    }
    .itaudit-sim-submit {
        width: 100%;
    }
}
/* --- completion message (v1.1.0) --- */
.ita-cm { font-family: monospace; color: #e6edf3; text-align: center; }
.ita-cm-score { font-size: 3rem; font-weight: 700; color: #00bfff; line-height: 1; }
.ita-cm-max { font-size: 1.1rem; color: #4b5563; }
.ita-cm-verdict { font-size: 1rem; text-transform: uppercase; letter-spacing: 0.1em; color: #ffa502; margin: 8px 0 14px; }
.ita-cm-debrief { font-size: 0.8rem; color: #8b949e; line-height: 1.6; margin-bottom: 16px; }
.ita-cm-kpis { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 16px; }
.ita-cm-kpi { background: #0d1117; border: 1px solid #1a2332; border-radius: 6px; padding: 10px; display: flex; flex-direction: column; gap: 4px; }
.ita-cm-kpi span { font-size: 0.58rem; text-transform: uppercase; letter-spacing: 0.08em; color: #4b5563; }
.ita-cm-kpi b { font-size: 1.05rem; color: #e6edf3; }
.ita-cm-insights { text-align: left; font-size: 0.78rem; color: #8b949e; line-height: 1.6; padding-left: 18px; margin: 0; }
.ita-cm-insights li { margin-bottom: 6px; }

