        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var results = { period: period };

            if (period === 1) {
                var priorityScores = { access_control: 92, audit_trail: 72, system_admin: 55, backup_recovery: 35 };
                var findingsScore = priorityScores[d.strategy] || 55;
                var hoursEffect = d.allocation / 100;
                var effectiveFindings = Math.round(findingsScore * hoursEffect);
                var riskReduction = effectiveFindings * 0.12;
                var cost = Math.round(d.allocation * 0.5);

                ds.budget -= cost;
                ds.riskScore = Math.max(0, Math.round(ds.riskScore - riskReduction));
                ds.complianceScore = Math.min(100, Math.round(ds.complianceScore + effectiveFindings * 0.15));

                results.findingsScore = effectiveFindings;
                results.riskReduction = Math.round(riskReduction);
                results.cost = cost;
            } else if (period === 2) {
                var approachScores = { forensic_deep: 92, sampling: 62, automated_scan: 42 };
                var baseEvidence = approachScores[d.strategy] || 62;
                var budgetEffect = d.allocation / 200;
                var evidenceQuality = Math.round(baseEvidence * (0.5 + 0.5 * budgetEffect));
                var anomaliesFound = Math.round(evidenceQuality * 0.55);
                var riskReduction2 = evidenceQuality * 0.15;
                var confidenceChange = evidenceQuality > 60 ? 6 : -4;

                ds.budget -= d.allocation;
                ds.riskScore = Math.max(0, Math.round(ds.riskScore - riskReduction2));
                ds.stakeholderConfidence = Math.min(100, Math.max(0, ds.stakeholderConfidence + confidenceChange));
                ds.complianceScore = Math.min(100, Math.round(ds.complianceScore + evidenceQuality * 0.1));
                ds.evidenceQuality = evidenceQuality;

                results.evidenceQuality = evidenceQuality;
                results.anomaliesFound = anomaliesFound;
                results.cost = d.allocation;
            } else if (period === 3) {
                var optionEffects = {
                    option_a: { confidence: 10, compliance: 20, risk: -15 },
                    option_b: { confidence: 0, compliance: 5, risk: -5 },
                    option_c: { confidence: -8, compliance: 25, risk: -20 }
                };
                var effects = optionEffects[d.strategy] || optionEffects.option_b;
                var adjustmentFit = 1 - Math.abs(d.allocation - 25) / 50;
                var adjustmentBonus = Math.round(adjustmentFit * 10);

                ds.stakeholderConfidence = Math.min(100, Math.max(0, ds.stakeholderConfidence + effects.confidence + adjustmentBonus));
                ds.complianceScore = Math.min(100, Math.max(0, ds.complianceScore + effects.compliance));
                ds.riskScore = Math.max(0, Math.round(ds.riskScore + effects.risk));
                ds.reserveAdjustment = d.allocation;

                results.confidenceChange = effects.confidence + adjustmentBonus;
                results.complianceChange = effects.compliance;
                results.riskChange = effects.risk;
                results.reserveAdjustment = d.allocation;
                results.cost = 0;
            } else if (period === 4) {
                var disclosureEffects = {
                    full_disclosure: { confidence: 15, compliance: 20, risk: -12 },
                    limited_disclosure: { confidence: 5, compliance: 10, risk: -5 },
                    minimal_disclosure: { confidence: -10, compliance: 0, risk: 5 }
                };
                var effects4 = disclosureEffects[d.strategy] || disclosureEffects.limited_disclosure;
                var budgetEffect4 = d.allocation / 800;
                var remediationScore = Math.round(budgetEffect4 * 100);

                ds.budget -= d.allocation;
                ds.stakeholderConfidence = Math.min(100, Math.max(0, ds.stakeholderConfidence + effects4.confidence));
                ds.complianceScore = Math.min(100, Math.max(0, ds.complianceScore + effects4.compliance + Math.round(remediationScore * 0.2)));
                ds.riskScore = Math.max(0, Math.round(ds.riskScore + effects4.risk - remediationScore * 0.15));

                results.remediationScore = remediationScore;
                results.confidenceChange = effects4.confidence;
                results.complianceChange = effects4.compliance + Math.round(remediationScore * 0.2);
                results.cost = d.allocation;
            }

            results.riskScore = ds.riskScore;
            results.complianceScore = ds.complianceScore;
            results.confidence = ds.stakeholderConfidence;
            results.budget = ds.budget;

            // --- GRADING CONTRACT: server reads domainState.performance.overallScore ---
            var composite = this._composite(ds);
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = composite;
            ds.performance.grade = this._grade(composite);
            ds.performance.tier = this._tier(composite);
            ds.performanceTier = this._tier(composite);
            results.overallScore = composite;
            results.score = composite;

            ds.riskHistory.push(ds.riskScore);
            ds.confidenceHistory.push(ds.stakeholderConfidence);
            ds.complianceHistory.push(ds.complianceScore);

            var self = this;
            if (state.currentPeriod < this.ROUNDS.length) {
                setTimeout(((__eqilNext) => function() {
                    self._updateBriefing({ currentPeriod: __eqilNext });
                })(state.currentPeriod + 1), 500);
            }

            return results;
        }

