        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = (window.mySimulation && window.mySimulation.state) ? window.mySimulation.state.domainState : {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var finalRisk = (r.riskScore != null) ? r.riskScore : (ds.riskScore != null ? ds.riskScore : 85);
            var finalCompliance = (r.complianceScore != null) ? r.complianceScore : (ds.complianceScore || 30);
            var finalConfidence = (r.confidence != null) ? r.confidence : (ds.stakeholderConfidence || 70);
            var composite = (r.overallScore != null) ? r.overallScore : this._composite(ds);
            var tier = this._tier(composite);
            var T = function(k) { return window.mySimulation.t(k); };

            var insights = [];
            insights.push(T('insight_' + tier));
            if (finalRisk > 50) insights.push(T('insight_high_risk'));
            if (finalRisk <= 30) insights.push(T('insight_low_risk'));
            if (finalCompliance >= 70) insights.push(T('insight_high_compliance'));
            if (finalCompliance < 50) insights.push(T('insight_low_compliance'));
            if (finalConfidence >= 80) insights.push(T('insight_high_confidence'));
            if (finalConfidence < 50) insights.push(T('insight_low_confidence'));

            return {
                overallScore: composite,
                score: composite,
                totalScore: composite,
                compositeScore: composite,
                finalRisk: finalRisk,
                finalCompliance: finalCompliance,
                finalConfidence: finalConfidence,
                performance: tier,
                performanceLabel: this._cl('grade_' + tier, tier),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var T = function(k) { return window.mySimulation.t(k); };
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var verdict = s.performanceLabel || s.performance || '';
            var kpis = ''
                + '<div class="ita-cm-kpi"><span>' + T('risk_label') + '</span><b>' + Math.round(s.finalRisk || 0) + '/100</b></div>'
                + '<div class="ita-cm-kpi"><span>' + T('compliance_label') + '</span><b>' + Math.round(s.finalCompliance || 0) + '/100</b></div>'
                + '<div class="ita-cm-kpi"><span>' + T('confidence_label') + '</span><b>' + Math.round(s.finalConfidence || 0) + '/100</b></div>';
            var items = (s.insights || []).map(function(t) { return '<li>' + t + '</li>'; }).join('');
            return '<div class="ita-cm">'
                + '<div class="ita-cm-score">' + score + '<span class="ita-cm-max">/100</span></div>'
                + '<div class="ita-cm-verdict">' + verdict + '</div>'
                + '<div class="ita-cm-debrief">' + T('cm_debrief') + '</div>'
                + '<div class="ita-cm-kpis">' + kpis + '</div>'
                + '<ul class="ita-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (state.currentPeriod === 1 && results.findingsScore && results.findingsScore < 40) {
                return window.mySimulation.t('hint_low_findings');
            }
            if (state.currentPeriod === 2 && results.evidenceQuality && results.evidenceQuality < 50) {
                return window.mySimulation.t('hint_low_evidence');
            }
            if (state.domainState.riskScore > 60 && state.currentPeriod >= 3) {
                return window.mySimulation.t('hint_high_risk');
            }
            if (state.domainState.budget < 50) {
                return window.mySimulation.t('hint_low_budget');
            }
            return null;
        }

