        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl && window.mySimulation) titleEl.textContent = window.mySimulation.t(round.titleKey);

            var descEl = document.getElementById('briefingText');
            if (descEl && window.mySimulation) descEl.innerHTML = window.mySimulation.t(round.descKey);

            var selLabel = document.getElementById('selectLabel');
            if (selLabel && window.mySimulation) selLabel.textContent = window.mySimulation.t(round.selectLabelKey);

            var numLabel = document.getElementById('numberLabel');
            if (numLabel && window.mySimulation) numLabel.textContent = window.mySimulation.t(round.numberLabelKey);

            var hintEl = document.getElementById('inputHint');
            if (hintEl && window.mySimulation) hintEl.textContent = window.mySimulation.t(round.hintKey);

            var selEl = document.getElementById('strategySelect');
            if (selEl && window.mySimulation) {
                selEl.innerHTML = '';
                for (var i = 0; i < round.options.length; i++) {
                    var opt = document.createElement('option');
                    opt.value = round.options[i].value;
                    opt.textContent = window.mySimulation.t(round.options[i].key);
                    selEl.appendChild(opt);
                }
            }

            var numEl = document.getElementById('budgetInput');
            if (numEl) {
                numEl.min = round.numberMin;
                numEl.max = round.numberMax;
                numEl.step = round.numberStep;
                numEl.value = round.numberDefault;
            }
        }
